package com.finsightai.service;
import com.finsightai.dto.*; import com.finsightai.security.JwtService; import org.springframework.security.authentication.*; import org.springframework.security.core.userdetails.UserDetails; import org.springframework.stereotype.Service;
@Service public class AuthService {private final AuthenticationManager manager; private final com.finsightai.security.CustomUserDetailsService users; private final JwtService jwt; public AuthService(AuthenticationManager m,com.finsightai.security.CustomUserDetailsService u,JwtService j){manager=m;users=u;jwt=j;} public AuthResponse login(AuthRequest r){manager.authenticate(new UsernamePasswordAuthenticationToken(r.username(),r.password()));UserDetails u=users.loadUserByUsername(r.username());String role=u.getAuthorities().iterator().next().getAuthority().replace("ROLE_","");return new AuthResponse(jwt.generate(u),u.getUsername(),role);}}
